head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/elw_recv_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
scwin.vScrenID = "ULDSTF05940.xml";
scwin.clickBzProcsNo = "";
scwin.readOnlyYn = "Y";
scwin.procJob = "";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/*익일영업일 가져옴*/
scwin.fn_getDate = function() {
    var url = "/listingCommon.do?method=listGeneral&outputMessageId=ULDSTF41001_INOUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstmgt.mktverif.date.select";
    dts_getDate.DataID = encodeURI(url);
    dts_getDate.reset();
};
scwin.fn_OpenDetail = function(row, dtsObj) {
    scwin.fn_setBzProcsNo(row, dtsObj);
    var vbzTpCd = dtsObj.getCellData(row, "LIST_BZ_TP_CD");
    $c.elw.fn_OpenDetailRecv(vbzTpCd);
};
scwin.fn_set_code = function() {
    dts_ElwInst.DataID = "/CodeAction.do?method=listWrntCd&For=R";
    dts_ElwInst.Reset();
    //alert("call");

};



/**
 * 추가상장신청시의 업무구분코드 가져오기
 */
scwin.fn_getListBzTpCd = function(str) {
    var val = '';
    if (str == LIST_BZ_TP_CD_002) {
        val = LIST_BZ_TP_CD_004;
    } else if (str == LIST_BZ_TP_CD_003) {
        val = LIST_BZ_TP_CD_005;
    }
    return val;
};
scwin.fn_list_sync = function() {
    if (MaxTab_01.getSelectedTabIndex() == 1) {
        $c.stf.showObj(btn_RcvPrc, true);
        txb_TDD_CLSPRC.setDisabled(false);
        if (!scwin.fn_CheckForm("1")) {
            return;
        }
        var url = "/ElwListedReceive.do?method=listElwKoLstRejRequest&inputMessageId=ELW_KO_LSTRCV_REJ_INOUT";
        url += "&TDD_CLSPRC=" + $c.stf.getObjectValue(txb_TDD_CLSPRC);
        url += "&TASK_DD=" + $c.stf.getObjectValue(edt_TASK_DD);
        //			url += "&CALND_DD=" + dts_getDate.NameString(1, "CALND_DD");
        url += "&SCREN_ID=" + scwin.vScrenID;
        url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        dts_List_1.DataID = encodeURI(url);
        dts_List_1.Reset();
        $c.cm.ShowWin(grd_List_1);
    } else if (MaxTab_01.getSelectedTabIndex() == 2) {
        $c.stf.showObj(btn_RcvPrc, false);
        txb_TDD_CLSPRC.setDisabled(true);
        var url = "/ElwListedReceive.do?method=listElwKoLstRejDtlRequest&inputMessageId=ELW_KO_LSTRCV_REJ_INOUT";
        url += "&TASK_DD=" + $c.stf.getObjectValue(edt_TASK_DD);
        url += "&SCREN_ID=" + scwin.vScrenID;
        url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        dts_List_2.DataID = encodeURI(url);
        dts_List_2.Reset();
        $c.cm.ShowWin(grd_List_2);
    }
};
scwin.fn_setBzProcsNo = function(obj, dtsObj) {
    scwin.clickBzProcsNo = dtsObj.getCellData(eval(obj), "BZ_PROCS_NO");
    //alert("fn_setBzProcsNo():"+clickBzProcsNo);

};
scwin.fn_getDataSet = function() {
    var dtsObj;
    if (MaxTab_01.getSelectedTabIndex() == 1) {
        dtsObj = dts_List_1;
    } else if (MaxTab_01.getSelectedTabIndex() == 2) {
        dtsObj = dts_List_2;
    }
    return dtsObj;
};
scwin.fn_selectIsuCheckCnt = function(dtsObj) {
    var k = 0;
    for (var i = 1; i <= dtsObj.getTotalRow(); i++) {
        if (dtsObj.getCellData(i, "CHECK") == "T") {
            k++;
        }
    }
    return k;
};
scwin.fn_CheckForm = function(procTyp) {
    if (procTyp == "1") {
        if ($c.stf.getObjectValue(txb_TDD_CLSPRC) == "") {
            $c.win.alert("[당일종가]를 입력하세요.");
            txb_TDD_CLSPRC.focus();
            return false;
        }
    }
    return true;
};
scwin.fn_packacpt = function() {
    var dtsObj = scwin.fn_getDataSet();

    // 해당이 아닌 항목을 체크 할 경우 화면에서 체크해야 함.
    for (var i = 1; i <= dtsObj.getTotalRow(); i++) {
        if (dtsObj.getCellData(i, "CHECK") == "T") {
            if (dtsObj.getCellData(i, "KO_LST_REJ_YN") != "해당") {
                $c.win.alert("상장거부여부 항목에 [ 해당 ] 인 경우만 선택하고 저장할수 있습니다.");
                return;
            }
        }
    }
    if (!scwin.fn_CheckForm("1")) {
        return;
    }
    if ($c.stf.getObjectValue(txb_TDD_CLSPRC) != dtsObj.getCellData(1, "TDD_CLSPRC")) {
        $c.win.alert("[입력한 당일종가]와 [검색한 당일종가] 다릅니다. 다시 조회하시고 저장하세요.");
        txb_TDD_CLSPRC.focus();
        return;
    }
    var vSelectCnt = scwin.fn_selectIsuCheckCnt(dtsObj);
    if (vSelectCnt == 0) {
        $c.win.alert("[종목]을 선택하세요.");
        return;
    }
    scwin.procJob = ' 선택한 ' + vSelectCnt + '종목에대한  저장처리 ';
    var res = window.confirm($c.stf.getMessageParam('MSG-A006', scwin.procJob));
    if (res) {
        //dts_Isu.UserStatus(1) = TB_JOB_UPDATE;
        for (var i = 1; i <= dtsObj.getTotalRow(); i++) {
            if (dtsObj.getCellData(i, "CHECK") == "T") {
                dtsObj.setCellData(i, "LIST_PROCS_STAT_CD", ELW_RECV_PROC_CD_02);
                dtsObj.setCellData(i, "TDD_CLSPRC", $c.stf.getObjectValue(txb_TDD_CLSPRC));
                dtsObj.setCellData(i, "REG_EMP_NO", js_emp_no);
            }
        }

        //alert('[dtsObj]'+dtsObj.text);
        trs_Save.Action = $c.lc.fn_encodeNSession("/ElwListedReceive.do?method=receiveElwKoLstRej&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03);
        trs_Save.KeyName = "toinb_dataid4";
        if (MaxTab_01.getSelectedTabIndex() == 1) {
            trs_Save.KeyValue = "JSP(I:pInput=dts_List_1)";
        }
        trs_Save.Post();
    }
};




/********************************************** 
 * 함수명   : fn_ExcelDown()
 * 설명       : 정보를 excel로 다운 받는다.
 ***********************************************/
scwin.fn_ExcelDown = function() {
    if (MaxTab_01.getSelectedTabIndex() == 1) {
        $c.data.downloadGridViewExcel(grd_List_1, "조기종료충족에 의한 상장거부처리", "", "8");
    } else if (MaxTab_01.getSelectedTabIndex() == 2) {
        $c.data.downloadGridViewExcel(grd_List_2, "조기종료충족에 의한 상장거부처리내역", "", "8");
    }
};
scwin.btn_RcvPrc_onclick = function() {
    scwin.fn_packacpt();
};
scwin.btn_Search_onclick = function() {
    scwin.fn_list_sync();
};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    scwin.fn_ExcelDown();
};
scwin.dts_List_1_OnLoadError = function() {
    $c.stf.alert_error(dts_List_1);
};
scwin.dts_List_2_OnLoadError = function() {
    $c.stf.alert_error(dts_List_2);
};
scwin.grd_List_1_OnHeadCheckClick = function(col, colid, bCheck) {
    //alert('grd_List.OnHeadCheckClick('+col+','+ colid+','+ bCheck+')');
    $c.elw.fn_setCheckBox(grd_List_1, dts_List_1, bCheck);
};
scwin.grd_List_2_OnHeadCheckClick = function(col, colid, bCheck) {
    $c.elw.fn_setCheckBox(grd_List_2, dts_List_2, bCheck);
};
scwin.dts_List_1_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    $c.cm.CloseWin(rowcount, grd_List_1);
};
scwin.dts_List_2_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    $c.cm.CloseWin(rowcount, grd_List_2);
};
scwin.grd_List_1_OnDblClick = function(row, colid) {
    if (colid == 'ISU_KOR_ABBRV') {
        scwin.fn_OpenDetail(row, dts_List_1);
    }
};
scwin.grd_List_2_OnDblClick = function(row, colid) {
    if (colid == 'ISU_KOR_ABBRV') {
        scwin.fn_OpenDetail(row, dts_List_2);
    }
};
scwin.trs_Save_OnFail = function() {
    fn_CheckForm;
    $c.win.alert($c.stf.getMessageParam("MSG-A002", scwin.procJob));
    $c.stf.alert_error(trs_Save);
};
scwin.trs_Save_OnSuccess = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0001", scwin.procJob));
    scwin.fn_list_sync();
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.MaxTab_01_OnSelChanged = function(nIndex) {
    scwin.fn_list_sync();
};
scwin.gform_onload = function() {
    MaxTab_01.setSelectedTabIndex(1);
    scwin.fn_set_code();
    scwin.fn_getDate();
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    $c.stf.setObjectValue(edt_TASK_DD, vCurDate);
    $c.cm.PanelToGroupBox(panel_Top);
    $c.stf.showObj(btn_RcvPrc, true);
    //	fn_list_sync();

};
scwin.img_TASK_DD_onclick = function() {
    popUpCalendar2(edt_TASK_DD);
};
scwin.grd_List_1_CanColumnPosChange = function(row, colid) {
    return true;
};
